-- CMS S2 (DP-017, DP-134, ADR-020 D6): publication of CMS pages.
--
-- Runs as dp_owner (ADR-012A). Additive only: two tables, one unique index on CmsPage (the target
-- of the composite keys), CHECK constraints and a guard trigger. No existing column or row
-- changes. Publishing copies the draft into an immutable revision; the page's single publication
-- points at a revision of the same page and site (composite foreign keys). dp_app may insert
-- revisions but never change or delete them, and may never delete a publication.
--
-- Part 1 is generated by `prisma migrate diff --from-schema <main> --to-schema schema.prisma`.
-- Part 2 adds the rules Prisma cannot model; test/integration/cms.int.test.ts covers each one.
-- Like CmsPage, both tables are site-bound in the site-scoped client and have no row-level
-- security (ADR-020 D5).

-- ===========================================================================================
-- Part 0: preconditions
-- ===========================================================================================

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'dp_app') THEN
    RAISE EXCEPTION 'CMS S2: role dp_app missing; ADR-012A must be applied first';
  END IF;
  IF to_regclass('public."CmsPage"') IS NULL THEN
    RAISE EXCEPTION 'CMS S2: CmsPage missing; migration 20261126090000_cms_s1_pages must be applied first';
  END IF;
END $$;

-- ===========================================================================================
-- Part 1: tables and indexes (generated)
-- ===========================================================================================

-- CreateTable
CREATE TABLE "CmsPageRevision" (
    "id" UUID NOT NULL,
    "pageId" UUID NOT NULL,
    "siteId" UUID NOT NULL,
    "revisionNumber" INTEGER NOT NULL,
    "pageVersion" INTEGER NOT NULL,
    "title" VARCHAR(200) NOT NULL,
    "path" VARCHAR(120),
    "seoTitle" VARCHAR(120),
    "seoDescription" VARCHAR(320),
    "noindex" BOOLEAN NOT NULL,
    "content" JSONB NOT NULL,
    "schemaVersion" INTEGER NOT NULL,
    "createdById" UUID NOT NULL,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "CmsPageRevision_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "CmsPagePublication" (
    "id" UUID NOT NULL,
    "pageId" UUID NOT NULL,
    "siteId" UUID NOT NULL,
    "revisionId" UUID NOT NULL,
    "status" "PublicationStatus" NOT NULL,
    "publishedAt" TIMESTAMPTZ(3) NOT NULL,
    "publishedById" UUID NOT NULL,
    "unpublishedAt" TIMESTAMPTZ(3),
    "unpublishedById" UUID,
    "version" INTEGER NOT NULL DEFAULT 1,
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "CmsPagePublication_pkey" PRIMARY KEY ("id")
);

-- CreateIndex
CREATE INDEX "CmsPageRevision_siteId_idx" ON "CmsPageRevision"("siteId");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPageRevision_pageId_revisionNumber_key" ON "CmsPageRevision"("pageId", "revisionNumber");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPageRevision_id_pageId_key" ON "CmsPageRevision"("id", "pageId");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPagePublication_pageId_key" ON "CmsPagePublication"("pageId");

-- CreateIndex
CREATE INDEX "CmsPagePublication_siteId_status_idx" ON "CmsPagePublication"("siteId", "status");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPagePublication_pageId_siteId_key" ON "CmsPagePublication"("pageId", "siteId");

-- CreateIndex
CREATE UNIQUE INDEX "CmsPage_id_siteId_key" ON "CmsPage"("id", "siteId");

-- AddForeignKey
ALTER TABLE "CmsPageRevision" ADD CONSTRAINT "CmsPageRevision_pageId_siteId_fkey" FOREIGN KEY ("pageId", "siteId") REFERENCES "CmsPage"("id", "siteId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPageRevision" ADD CONSTRAINT "CmsPageRevision_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPageRevision" ADD CONSTRAINT "CmsPageRevision_createdById_fkey" FOREIGN KEY ("createdById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPagePublication" ADD CONSTRAINT "CmsPagePublication_pageId_siteId_fkey" FOREIGN KEY ("pageId", "siteId") REFERENCES "CmsPage"("id", "siteId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPagePublication" ADD CONSTRAINT "CmsPagePublication_revisionId_pageId_fkey" FOREIGN KEY ("revisionId", "pageId") REFERENCES "CmsPageRevision"("id", "pageId") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPagePublication" ADD CONSTRAINT "CmsPagePublication_siteId_fkey" FOREIGN KEY ("siteId") REFERENCES "Site"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPagePublication" ADD CONSTRAINT "CmsPagePublication_publishedById_fkey" FOREIGN KEY ("publishedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- AddForeignKey
ALTER TABLE "CmsPagePublication" ADD CONSTRAINT "CmsPagePublication_unpublishedById_fkey" FOREIGN KEY ("unpublishedById") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

-- ===========================================================================================
-- Part 2: consistency (CHECK) and immutable revisions
-- ===========================================================================================

ALTER TABLE "CmsPageRevision"
  ADD CONSTRAINT "CmsPageRevision_numbers_positive"
    CHECK ("revisionNumber" >= 1 AND "pageVersion" >= 1 AND "schemaVersion" >= 1),
  ADD CONSTRAINT "CmsPageRevision_content_object" CHECK (jsonb_typeof("content") = 'object'),
  ADD CONSTRAINT "CmsPageRevision_title_trimmed"
    CHECK ("title" = btrim("title") AND length("title") >= 1),
  ADD CONSTRAINT "CmsPageRevision_path_format"
    CHECK ("path" IS NULL OR "path" ~ '^/([a-z0-9]+(-[a-z0-9]+)*)?$');

ALTER TABLE "CmsPagePublication"
  -- UNPUBLISHED carries who withdrew it and when; PUBLISHED carries neither.
  ADD CONSTRAINT "CmsPagePublication_status_fields" CHECK (
    ("status" = 'PUBLISHED') = ("unpublishedAt" IS NULL)
    AND ("unpublishedAt" IS NULL) = ("unpublishedById" IS NULL)
  ),
  ADD CONSTRAINT "CmsPagePublication_version_positive" CHECK ("version" >= 1);

-- A published revision is a record: it never changes and is never removed (also for dp_owner).
CREATE FUNCTION cms_revision_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'cms: a published revision cannot be changed or deleted';
END $$;

CREATE TRIGGER "CmsPageRevision_immutable"
  BEFORE UPDATE OR DELETE ON "CmsPageRevision"
  FOR EACH ROW EXECUTE FUNCTION cms_revision_immutable();

-- ===========================================================================================
-- Part 3: privileges
-- ===========================================================================================

REVOKE UPDATE, DELETE ON TABLE "CmsPageRevision" FROM dp_app;
REVOKE DELETE ON TABLE "CmsPagePublication" FROM dp_app;
